<?php /** @var array<string,mixed> $i */ /** @var list<array<string,mixed>> $items */ /** @var array<string,mixed> $bal */ /** @var list<array<string,mixed>> $payments */ /** @var list<array<string,mixed>> $creditNotes */ /** @var bool $canCredit */ /** @var int $creditable */ /** @var bool $canEdit */ /** @var bool $canIssue */ /** @var bool $canVoid */ /** @var bool $canRecord */
/** @var bool $profileOk */ /** @var array<string,string> $methods */ /** @var list<array<string,mixed>> $projects */ $url = '/invoices/' . $i['public_id']; $st = $i['status']; $v = static fn (string $k, string $d = ''): string => old($k, $d);
$labels = ['draft' => 'Draft', 'issued' => 'Issued', 'partially_paid' => 'Partially paid', 'paid' => 'Paid', 'void' => 'Void']; ?>
<div class="page-head"><div><p class="eyebrow">Invoice</p><h1><?= e($i['reference'] ?? 'Draft invoice') ?> · <?= e($i['title']) ?></h1></div><div class="actions"><?php if ($st !== 'draft') : ?><a class="btn btn-ghost" href="<?= e($url) ?>/print">Print view</a><?php endif; ?><?php if (in_array($st, ['issued', 'partially_paid'], true) && can('payments.request')) : ?><a class="btn btn-primary" href="<?= e($url) ?>/phonepe">Request PhonePe payment</a><?php endif; ?><a class="btn btn-ghost" href="<?= e($url) ?>/pdf">Download PDF</a><a class="btn btn-ghost" href="/invoices">&larr; Invoices</a></div></div>
<?php if ($bal['overdue']) : ?><div class="alert alert-error" role="status"><p><strong>Overdue</strong> since <?= e(local_date($i['due_date'])) ?>.</p></div><?php endif; ?>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><span class="badge badge-bi-<?= e($st) ?>"><?= e($labels[$st] ?? $st) ?></span></div><div><span class="muted">Client</span><br><a href="/clients/<?= e($i['client_public_id']) ?>"><?= e($i['client_name']) ?></a></div>
    <div><span class="muted">Total</span><br><strong><?= e(money($i['total_minor'])) ?></strong></div><div><span class="muted">Paid / outstanding</span><br><?= e(money($bal['paid'])) ?> / <?= e(money($bal['outstanding'])) ?><?= $bal['pending'] > 0 ? '<br><span class="muted">' . e(money($bal['pending'])) . ' awaiting verification</span>' : '' ?></div></div>
    <dl class="detail-list"><?php if ($i['issue_date']) : ?><dt>Issued</dt><dd><?= e(local_date($i['issue_date'])) ?></dd><?php endif; ?><dt>Due</dt><dd><?= $i['due_date'] ? e(local_date($i['due_date'])) : 'default 14 days after issue' ?></dd>
        <?php if ($i['project_public_id']) : ?><dt>Project</dt><dd><a href="/projects/<?= e($i['project_public_id']) ?>"><?= e($i['project_code']) ?></a></dd><?php endif; ?><?php if ($i['quotation_public_id']) : ?><dt>Quotation</dt><dd><a href="/quotations/<?= e($i['quotation_public_id']) ?>"><?= e($i['quotation_reference']) ?></a></dd><?php endif; ?>
        <?php if ($st === 'void') : ?><dt>Voided</dt><dd><?= e(local_time($i['voided_at'])) ?> · <?= e($i['void_reason']) ?></dd><?php endif; ?></dl>
    <?= \Vertex\Core\View::partial('billing-lines', ['items' => $items, 'subtotal' => (int) $i['subtotal_minor'], 'discount' => (int) $i['discount_minor'], 'total' => (int) $i['total_minor'], 'coupon' => (int) $i['coupon_discount_minor'] > 0 ? [$i['coupon_code'], (int) $i['coupon_discount_minor']] : null, 'credited' => (int) $i['credited_minor']]) ?>
    <?php if ($i['client_notes']) : ?><h3>Notes for the client</h3><p class="prewrap"><?= e($i['client_notes']) ?></p><?php endif; ?>
    <?php if ($i['internal_notes']) : ?><h3>Internal notes <span class="badge badge-sensitive">staff only</span></h3><p class="prewrap"><?= e($i['internal_notes']) ?></p><?php endif; ?></div>
<?php if ($payments !== []) : ?><div class="panel"><h2>Payments</h2><div class="table-wrap"><table class="table"><thead><tr><th>Payment</th><th>Method</th><th>Reference</th><th>Date</th><th class="num">Amount</th><th>Status</th></tr></thead><tbody>
    <?php foreach ($payments as $p) : ?><tr><td><a href="/client-payments/<?= e($p['public_id']) ?>"><?= e($p['reference']) ?></a><?= $p['source'] === 'client_claim' ? '<br><span class="muted">submitted by the client</span>' : '' ?></td><td><?= e(config("referrals.payment_methods.{$p['method']}", $p['method'])) ?></td><td><?= e($p['external_ref']) ?></td><td><?= e(local_date($p['received_on'])) ?></td><td class="num"><?= e(money($p['gross_minor'])) ?></td><td><?= \Vertex\Core\View::partial('pbadge', ['kind' => 'payment', 's' => $p['status']]) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<?php if ($st === 'draft' && $canIssue) : ?><div class="panel"><h2>Issue</h2><?php if (!$profileOk) : ?><p>Set your business details first (Administration → Business details).</p><?php else : ?><p class="muted">Issuing assigns the invoice number, freezes the content and notifies the client. It can no longer be edited (only voided).</p>
    <form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Issue this invoice? It cannot be edited afterwards."><?= csrf_field() ?><input type="hidden" name="action" value="issue"><div class="field"><label for="ipw">Your password</label><input id="ipw" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Issue invoice</button></div></form><?php endif; ?></div><?php endif; ?>
<?php if ($st === 'draft' && $canEdit) : ?><div class="panel"><h2>Edit draft</h2><form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="edit">
    <div class="field"><label for="p">Project</label><select id="p" name="project"><option value="">None</option><?php foreach ($projects as $p) : ?><option value="<?= e($p['public_id']) ?>"<?= ($i['project_public_id'] ?? '') === $p['public_id'] ? ' selected' : '' ?>><?= e($p['code']) ?> · <?= e($p['title']) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="t">Title</label><input id="t" name="title" required maxlength="200" value="<?= e($v('title', $i['title'])) ?>"></div><div class="field"><label for="d">Due date</label><input id="d" name="due_date" type="date" value="<?= e($v('due_date', (string) $i['due_date'])) ?>"></div>
    <?= \Vertex\Core\View::partial('billing-items', ['items' => $items]) ?>
    <div class="field"><label for="di">Discount (₹)</label><input id="di" name="discount" inputmode="decimal" value="<?= e($v('discount', number_format((int) $i['discount_minor'] / 100, 2, '.', ''))) ?>"></div>
    <div class="field"><label for="cc">Coupon code (optional)</label><input id="cc" name="coupon_code" maxlength="30" value="<?= e($v('coupon_code', (string) ($i['coupon_code'] ?? ''))) ?>" autocomplete="off"></div>
    <div class="field"><label for="cn">Notes for the client</label><textarea id="cn" name="client_notes" rows="3" maxlength="3000"><?= e($v('client_notes', (string) $i['client_notes'])) ?></textarea></div><div class="field"><label for="in">Internal notes</label><textarea id="in" name="internal_notes" rows="2" maxlength="3000"><?= e($v('internal_notes', (string) $i['internal_notes'])) ?></textarea></div>
    <div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Save</button></div></form></div><?php endif; ?>
<?php if (in_array($st, ['issued', 'partially_paid'], true) && $canRecord) : ?><div class="panel"><h2>Record a payment you received</h2><p class="muted">Record only money that arrived. It counts after a second person verifies it against the bank (Client payments). Still due: <?= e(money(max(0, $bal['outstanding'] - $bal['pending']))) ?>.</p>
    <form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="payment">
        <div class="field"><label for="pg">Amount (₹)</label><input id="pg" name="gross" required inputmode="decimal" value="<?= e($v('gross')) ?>"></div>
        <div class="field"><label for="pm">Method</label><select id="pm" name="method"><?php foreach ($methods as $c => $l) : ?><option value="<?= e($c) ?>"><?= e($l) ?></option><?php endforeach; ?></select></div>
        <?php if ($i['project_public_id']) : ?><div class="field"><label for="pr">This payment is the</label><select id="pr" name="role"><option value="advance">Advance</option><option value="balance">Balance / final</option><option value="other">Other</option></select></div><?php endif; ?>
        <div class="field"><label for="px">Transaction reference (UTR / UPI ref)</label><input id="px" name="external_ref" required maxlength="120" value="<?= e($v('external_ref')) ?>"></div><div class="field"><label for="po">Date received</label><input id="po" name="received_on" type="date" required></div>
        <div class="field"><label for="pn">Notes</label><input id="pn" name="notes" maxlength="500"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Record payment</button></div></form></div><?php endif; ?>
<?php if ($st !== 'draft' && ($creditNotes !== [] || ($canCredit && $creditable > 0 && in_array($st, ['issued', 'partially_paid'], true)))) : ?><div class="panel"><h2>Credit notes</h2>
    <?php if ($creditNotes !== []) : ?><div class="table-wrap"><table class="table"><thead><tr><th>Credit note</th><th>Reason</th><th class="num">Amount</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($creditNotes as $n) : ?><tr><td><a href="/credit-notes/<?= e($n['public_id']) ?>"><?= e($n['reference']) ?></a><br><span class="muted"><?= e(local_date(substr((string) $n['issued_at'], 0, 10))) ?></span></td><td><?= e($n['reason']) ?></td><td class="num"><?= e(money((int) $n['amount_minor'])) ?></td><td><?= $n['status'] === 'void' ? 'Void: ' . e((string) $n['void_reason']) : 'Issued' ?></td>
        <td><?php if ($n['status'] === 'issued' && $canCredit) : ?><form method="post" action="<?= e($url) ?>" class="inline-form" data-confirm="Void this credit note?"><?= csrf_field() ?><input type="hidden" name="action" value="void_credit_note"><input type="hidden" name="note" value="<?= e($n['public_id']) ?>"><input name="reason" placeholder="Reason" required minlength="10" maxlength="255" aria-label="Reason"><input name="confirm_password" type="password" placeholder="Your password" required autocomplete="current-password" aria-label="Your password"><button class="btn btn-ghost btn-sm" type="submit">Void</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    <?php if ($canCredit && $creditable > 0 && in_array($st, ['issued', 'partially_paid'], true)) : ?><p class="muted">A credit note reduces what the client still owes (up to <?= e(money($creditable)) ?>). Money already received is returned through a refund instead. To cancel the whole invoice use Void.</p>
    <form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Issue this credit note? It cannot be edited, only voided."><?= csrf_field() ?><input type="hidden" name="action" value="credit_note">
        <div class="field"><label for="ca">Credit amount (₹)</label><input id="ca" name="amount" required inputmode="decimal"></div><div class="field"><label for="cr">Reason (required)</label><input id="cr" name="reason" required minlength="10" maxlength="255"></div>
        <div class="field"><label for="cpw">Your password</label><input id="cpw" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-primary btn-sm" type="submit">Issue credit note</button></div></form><?php endif; ?></div><?php endif; ?>
<?php if (in_array($st, ['draft', 'issued', 'partially_paid'], true) && $canVoid) : ?><div class="panel"><h2>Void</h2><p class="muted">An invoice with money on it (or a payment awaiting verification) cannot be voided: reject or refund those first. The number is never reused.</p>
    <form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Void this invoice?"><?= csrf_field() ?><input type="hidden" name="action" value="void"><div class="field"><label for="vr">Reason (required)</label><input id="vr" name="reason" required minlength="10" maxlength="255" value="<?= e($v('reason')) ?>"></div>
        <div class="field"><label for="vpw">Your password</label><input id="vpw" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-danger btn-sm" type="submit">Void invoice</button></div></form></div><?php endif; ?>
